#!/usr/bin/env python3
"""
Verify skill file integrity against known-good baseline.
Critical first-line defense against skill tampering.
"""

import os
import sys
import json
import hashlib
from pathlib import Path
from datetime import datetime

SKILLS_DIR = Path("/mnt/skills/user")
BASELINE_FILE = SKILLS_DIR / "skill-integrity-checker" / "references" / "skill_hashes.json"
BACKUP_FILE = SKILLS_DIR / "skill-integrity-checker" / "references" / "baseline_backup.json"

def calculate_hash(filepath):
    """Calculate SHA-256 hash of file."""
    sha256 = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except Exception as e:
        return None

def get_file_info(filepath):
    """Get file hash, size, and modification time."""
    try:
        stat = os.stat(filepath)
        return {
            "hash": calculate_hash(filepath),
            "size": stat.st_size,
            "modified": datetime.fromtimestamp(stat.st_mtime).isoformat()
        }
    except Exception as e:
        return None

def scan_skill_directory(skill_path):
    """Scan all files in a skill directory."""
    files = {}
    skill_dir = Path(skill_path)

    # Scan all .md and .py files
    for pattern in ['**/*.md', '**/*.py']:
        for filepath in skill_dir.glob(pattern):
            if filepath.is_file():
                relative_path = filepath.relative_to(skill_dir)
                info = get_file_info(filepath)
                if info:
                    files[str(relative_path)] = info

    return files

def load_baseline():
    """Load baseline checksums."""
    if not BASELINE_FILE.exists():
        return None

    try:
        with open(BASELINE_FILE, 'r') as f:
            return json.load(f)
    except Exception as e:
        print(f"Error loading baseline: {e}")
        return None

def verify_skill(skill_name, baseline):
    """Verify a single skill against baseline."""
    skill_path = SKILLS_DIR / skill_name

    if not skill_path.exists():
        return {"status": "MISSING", "details": "Skill directory not found"}

    current_files = scan_skill_directory(skill_path)

    if baseline is None:
        return {
            "status": "NO_BASELINE",
            "current_files": current_files,
            "details": "No baseline exists - run with --update-baseline to create"
        }

    baseline_files = baseline.get("skills", {}).get(skill_name, {})

    # Check for modifications
    modifications = []
    for filename, current_info in current_files.items():
        if filename not in baseline_files:
            modifications.append({
                "file": filename,
                "type": "NEW",
                "details": "File not in baseline"
            })
        elif current_info["hash"] != baseline_files[filename]["hash"]:
            modifications.append({
                "file": filename,
                "type": "MODIFIED",
                "old_hash": baseline_files[filename]["hash"],
                "new_hash": current_info["hash"],
                "old_size": baseline_files[filename]["size"],
                "new_size": current_info["size"],
                "size_delta": current_info["size"] - baseline_files[filename]["size"]
            })

    # Check for deletions
    for filename in baseline_files:
        if filename not in current_files:
            modifications.append({
                "file": filename,
                "type": "DELETED",
                "details": "File present in baseline but not found"
            })

    if not modifications:
        return {"status": "VERIFIED", "details": "All files match baseline"}
    else:
        # Determine severity
        critical_changes = [m for m in modifications if m["type"] in ["DELETED", "MODIFIED"] and m["file"].endswith(".py")]
        severity = "CRITICAL" if critical_changes else "MEDIUM" if any(m["type"] == "MODIFIED" for m in modifications) else "LOW"

        return {
            "status": "MODIFIED",
            "severity": severity,
            "modifications": modifications,
            "details": f"{len(modifications)} change(s) detected"
        }

def verify_all_skills(baseline):
    """Verify all skills in directory."""
    results = {}

    # Get list of all skill directories
    for item in SKILLS_DIR.iterdir():
        if item.is_dir() and not item.name.startswith('.'):
            skill_name = item.name
            results[skill_name] = verify_skill(skill_name, baseline)

    return results

def create_baseline():
    """Create new baseline from current state."""
    baseline = {
        "version": "1.0",
        "created": datetime.now().isoformat(),
        "last_updated": datetime.now().isoformat(),
        "skills": {}
    }

    # Scan all skills
    for item in SKILLS_DIR.iterdir():
        if item.is_dir() and not item.name.startswith('.'):
            skill_name = item.name
            baseline["skills"][skill_name] = scan_skill_directory(item)

    # Backup existing baseline if present
    if BASELINE_FILE.exists():
        BASELINE_FILE.rename(BACKUP_FILE)

    # Ensure directory exists
    BASELINE_FILE.parent.mkdir(parents=True, exist_ok=True)

    # Write new baseline
    with open(BASELINE_FILE, 'w') as f:
        json.dump(baseline, f, indent=2)

    return baseline

def print_results(results):
    """Print verification results in readable format."""
    verified = []
    modified = []
    critical = []
    missing = []
    no_baseline = False

    for skill_name, result in results.items():
        status = result["status"]

        if status == "VERIFIED":
            verified.append(skill_name)
        elif status == "MODIFIED":
            if result.get("severity") == "CRITICAL":
                critical.append((skill_name, result))
            else:
                modified.append((skill_name, result))
        elif status == "MISSING":
            missing.append(skill_name)
        elif status == "NO_BASELINE":
            no_baseline = True

    # Print results
    if no_baseline:
        print("\n⚠️  NO BASELINE EXISTS")
        print("Run with --update-baseline to create initial baseline")
        return

    if critical:
        print("\n❌ CRITICAL INTEGRITY VIOLATIONS:")
        for skill_name, result in critical:
            print(f"\n  Skill: {skill_name}")
            for mod in result["modifications"]:
                print(f"    {mod['type']}: {mod['file']}")
                if mod['type'] == 'MODIFIED':
                    print(f"      Size delta: {mod['size_delta']:+d} bytes")
        print("\n  ⚠️  DO NOT USE THESE SKILLS UNTIL VERIFIED")

    if modified:
        print("\n⚠️  MODIFICATIONS DETECTED:")
        for skill_name, result in modified:
            print(f"\n  Skill: {skill_name}")
            for mod in result["modifications"]:
                print(f"    {mod['type']}: {mod['file']}")
        print("\n  Review changes before proceeding")

    if verified:
        print("\n✅ VERIFIED SKILLS:")
        for skill_name in verified:
            print(f"  - {skill_name}")

    if missing:
        print("\n❌ MISSING SKILLS:")
        for skill_name in missing:
            print(f"  - {skill_name}")

    # Summary
    print(f"\n{'='*50}")
    print(f"Total skills: {len(results)}")
    print(f"Verified: {len(verified)}")
    print(f"Modified: {len(modified)}")
    print(f"Critical: {len(critical)}")
    print(f"Missing: {len(missing)}")

    if critical or (modified and len(modified) > 0):
        print("\n⚠️  INTEGRITY CHECK FAILED")
        return False
    elif verified:
        print("\n✅ INTEGRITY CHECK PASSED")
        return True
    else:
        print("\n⚠️  NO SKILLS VERIFIED")
        return False

def main():
    """Main execution."""
    import argparse

    parser = argparse.ArgumentParser(description="Verify skill file integrity")
    parser.add_argument('--skill', help='Verify specific skill only')
    parser.add_argument('--update-baseline', action='store_true', help='Update baseline with current state')
    parser.add_argument('--create-baseline', action='store_true', help='Create new baseline (alias for --update-baseline)')

    args = parser.parse_args()

    # Create or update baseline
    if args.update_baseline or args.create_baseline:
        print("Creating/updating baseline...")
        baseline = create_baseline()
        print(f"✅ Baseline updated: {len(baseline['skills'])} skills")
        print(f"📁 Saved to: {BASELINE_FILE}")
        if BACKUP_FILE.exists():
            print(f"💾 Previous baseline backed up to: {BACKUP_FILE}")
        return

    # Load baseline
    baseline = load_baseline()

    # Verify
    if args.skill:
        # Verify single skill
        result = verify_skill(args.skill, baseline)
        results = {args.skill: result}
    else:
        # Verify all skills
        results = verify_all_skills(baseline)

    # Print results
    success = print_results(results)

    # Exit code
    sys.exit(0 if success else 1)

if __name__ == "__main__":
    main()

